package com.semes.reqops.domain.migration;
import com.semes.reqops.domain.migration.service.*; import lombok.RequiredArgsConstructor; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor @ConditionalOnProperty(name="reqops.migration.mode") public class MigrationRunner implements ApplicationRunner {private final LegacyDeliverableImporter importer;private final MigrationVerifier verifier;public void run(ApplicationArguments args){String mode=args.getOptionValues("reqops.migration.mode").get(0);if("import".equals(mode))System.out.println("legacy snapshots="+importer.snapshot());System.out.println("migration verification="+verifier.verify());}}
